glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 src = vec2(0.5, 0.85);
  vec3 acc = vec3(0.0);
  vec2 st = (uv - src) / 24.0;
  vec2 p = uv;
  for (int i = 0; i < 24; i++) {
    p -= st;
    vec3 s = getColor(p).rgb;
    acc += max(s - 0.6, 0.0) * (1.0 - float(i) / 24.0);
  }
  return vec4(c.rgb + acc * 0.18 * uAmount, c.a);
}
